"""Convert a 'Content-Range' header into a length for the response.

    Helper for :meth:`Response.length`.

    :type content_range: str
    :param content_range: the header value being parsed.

    :rtype: int
    :returns: the length of the response chunk.
    """
def _process_content_range(content_range: Any) -> object {
    (_, _, range_spec) = content_range.partition(' ');
    (byte_range, _, _) = range_spec.partition('/');
    (start, _, end) = byte_range.partition('-');
    return ((int(end) - int(start)) + 1);
}

"""Finds volume of a cuboid"""
def volCuboid(length: float, breadth: float, height: float) -> float {
    volume: float = length * breadth * height;
    return volume;
}

"""Convert a 'ownerlastvisit' sort directive into SQL."""
def _ProcessOwnerLastVisitSD(fmt: Any) -> object {
    left_joins = [
        (
            fmt(
                'User AS {alias} ON (Issue.owner_id = {alias}.user_id OR '
                'Issue.derived_owner_id = {alias}.user_id)'
            ),
            []
        )
    ];
    order_by = [
        (fmt('ISNULL({alias}.last_visit_timestamp) {sort_dir}'), []),
        (fmt('{alias}.last_visit_timestamp {sort_dir}'), [])
    ];
    return (left_joins, order_by);
}
